def processStr(s, k):
    n = len(s)
    lens = [0] * (n + 1)
    for i, c in enumerate(s):
        if c == '*':
            lens[i + 1] = max(0, lens[i] - 1)
        elif c == '#':
            lens[i + 1] = lens[i] * 2
        elif c == '%':
            lens[i + 1] = lens[i]
        else:
            lens[i + 1] = lens[i] + 1
    if k >= lens[n]:
        return '.'
    for i in range(n, 0, -1):
        c = s[i - 1]
        L = lens[i - 1]
        if c == '#':
            if k >= L:
                k -= L
        elif c == '%':
            k = L - 1 - k
        elif c == '*':
            pass
        else:
            if k == L:
                return c
    return '.'
